import functools

def _parse(v):
    core = v.split('+', 1)[0]
    if '-' in core:
        main, pre = core.split('-', 1)
    else:
        main, pre = core, None
    major, minor, patch = (int(x) for x in main.split('.'))
    pre_ids = pre.split('.') if pre is not None else None
    return (major, minor, patch, pre_ids)

def _cmp_id(a, b):
    a_num = a.isdigit()
    b_num = b.isdigit()
    if a_num and b_num:
        ai, bi = int(a), int(b)
        return (ai > bi) - (ai < bi)
    if a_num and not b_num:
        return -1
    if not a_num and b_num:
        return 1
    return (a > b) - (a < b)

def _cmp(v1, v2):
    a = _parse(v1)
    b = _parse(v2)
    for i in range(3):
        if a[i] != b[i]:
            return -1 if a[i] < b[i] else 1
    pre_a, pre_b = a[3], b[3]
    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1
    if pre_b is None:
        return -1
    for x, y in zip(pre_a, pre_b):
        c = _cmp_id(x, y)
        if c != 0:
            return c
    if len(pre_a) != len(pre_b):
        return -1 if len(pre_a) < len(pre_b) else 1
    return 0

def semver_sort(versions):
    return sorted(versions, key=functools.cmp_to_key(_cmp))

